// Differential probe harness for /workspace/dataset/test16_executable
// Usage:
//   node /workspace/tools/probe.mjs -e 'line1\nline2'      # md1(): convert ONE snippet, show html1
//   node /workspace/tools/probe.mjs --raw 'literal text'   # no backslash-escape interpretation
//   node /workspace/tools/probe.mjs --json '["snip1","snip2"]'   # batch, JSON in / JSON out
//   node /workspace/tools/probe.mjs --file snippets.json         # batch from file (JSON array)
//   node /workspace/tools/probe.mjs --full a b c d e             # full 5-arg program output
import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';

const EXE = '/workspace/dataset/test16_executable';
const SENT = 'ZQXSENTINELB';

export function runExe(a, b, c, d, e) {
  const r = spawnSync(EXE, ['--a', a, '--b', b, '--c', c, '--d', d, '--e', e], {
    encoding: 'utf8', maxBuffer: 1 << 28,
  });
  return { stdout: r.stdout ?? '', stderr: r.stderr ?? '', code: r.status };
}

// Convert a single markdown snippet and return exactly markdown.markdown(snippet).
export function md1(src) {
  const { stdout, code, stderr } = runExe(src, SENT, 'C', 'D', 'E');
  if (code !== 0) return { error: true, code, stderr };
  const marker = '\n<p>' + SENT + '</p>\n';
  const i = stdout.indexOf(marker);
  if (i < 0) return { error: true, code, stderr: 'sentinel not found', stdout };
  return { html: stdout.slice(0, i) };
}

function unescape(s) {
  let out = '';
  for (let i = 0; i < s.length; i++) {
    if (s[i] === '\\' && i + 1 < s.length) {
      const c = s[++i];
      if (c === 'n') out += '\n';
      else if (c === 't') out += '\t';
      else if (c === 'r') out += '\r';
      else if (c === '\\') out += '\\';
      else { out += '\\'; out += c; }
    } else out += s[i];
  }
  return out;
}

const argv = process.argv.slice(2);
if (argv.length) {
  const mode = argv[0];
  if (mode === '--full') {
    const [, a, b, c, d, e] = argv;
    const r = runExe(a ?? '', b ?? '', c ?? '', d ?? '', e ?? '');
    process.stdout.write(r.stdout);
    if (r.stderr) process.stderr.write(r.stderr);
    process.exitCode = r.code ?? 0;
  } else if (mode === '--json' || mode === '--file') {
    const src = mode === '--file' ? readFileSync(argv[1], 'utf8') : argv[1];
    const list = JSON.parse(src);
    const out = list.map((s) => {
      const r = md1(s);
      return { input: s, output: r.html ?? null, error: r.error ? (r.stderr || 'err') : undefined };
    });
    process.stdout.write(JSON.stringify(out, null, 1) + '\n');
  } else {
    const raw = mode === '--raw';
    const text = raw ? argv[1] : unescape(mode === '-e' ? argv[1] : mode);
    const r = md1(text);
    if (r.error) { process.stderr.write('ERROR ' + JSON.stringify(r) + '\n'); process.exitCode = 1; }
    else {
      process.stdout.write('INPUT_JSON:  ' + JSON.stringify(text) + '\n');
      process.stdout.write('OUTPUT_JSON: ' + JSON.stringify(r.html) + '\n');
      process.stdout.write('OUTPUT_RAW:\n⟦' + r.html + '⟧\n');
    }
  }
}

// Multiplexed probe harness: converts MANY snippets in ONE executable run.
// Usage: node /workspace/tools/fast.mjs snippets.json [chunkSize]
// Prints JSON [{input, output}]  (output = html for that snippet alone)
// Caveat: snippets share one document, so reference definitions leak between
// snippets and unterminated blocks can swallow the separator. Verified against
// probe.mjs (one-process-per-snippet) for paragraph-only snippets.
import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';

const EXE = '/workspace/dataset/test16_executable';
const SENT = 'ZQXSENTINELB';
const SEP = 'QXSEPQX';

function runDoc(src) {
  const r = spawnSync(EXE, ['--a', src, '--b', SENT, '--c', 'C', '--d', 'D', '--e', 'E'], {
    encoding: 'utf8', maxBuffer: 1 << 28,
  });
  const stdout = r.stdout ?? '';
  const marker = '\n<p>' + SENT + '</p>\n';
  const i = stdout.indexOf(marker);
  if (i < 0) throw new Error('sentinel missing: ' + JSON.stringify(stdout.slice(0, 400)) + ' stderr=' + r.stderr);
  return stdout.slice(0, i);
}

function trim1(s) {
  if (s.startsWith('\n')) s = s.slice(1);
  if (s.endsWith('\n')) s = s.slice(0, -1);
  return s;
}

export function mdMany(list, chunk = 120) {
  const res = [];
  for (let i = 0; i < list.length; i += chunk) {
    const part = list.slice(i, i + chunk);
    const doc = part.join('\n\n' + SEP + '\n\n');
    const html = runDoc(doc);
    const pieces = html.split('<p>' + SEP + '</p>');
    if (pieces.length !== part.length) {
      // fall back to one-at-a-time for this chunk
      for (const s of part) res.push(trim1(runDoc(s)));
    } else {
      for (const p of pieces) res.push(trim1(p));
    }
  }
  return res;
}

const argv = process.argv.slice(2);
if (argv.length) {
  const list = JSON.parse(readFileSync(argv[0], 'utf8'));
  const chunk = argv[1] ? parseInt(argv[1], 10) : 120;
  const outs = mdMany(list, chunk);
  process.stdout.write(JSON.stringify(list.map((s, i) => ({ input: s, output: outs[i] })), null, 1) + '\n');
}
// Direct argv probe harness for /workspace/dataset/test16_executable
// Usage: node cli.mjs --file cases.json   where cases.json = [ {name, argv:[...]} , ... ]  or [ [argv...], ... ]
import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';

const EXE = '/workspace/dataset/test16_executable';

function run(argv, opts = {}) {
  const r = spawnSync(EXE, argv, { encoding: 'utf8', maxBuffer: 1 << 28, ...opts });
  return {
    code: r.status,
    signal: r.signal ?? null,
    stdout: r.stdout ?? '',
    stderr: r.stderr ?? '',
  };
}

const argv = process.argv.slice(2);
if (argv[0] === '--file') {
  const list = JSON.parse(readFileSync(argv[1], 'utf8'));
  const out = list.map((c) => {
    const a = Array.isArray(c) ? c : c.argv;
    const name = Array.isArray(c) ? null : (c.name ?? null);
    const env = Array.isArray(c) ? undefined : c.env;
    const r = run(a, env ? { env: { ...process.env, ...env } } : {});
    return { name, argv: a, code: r.code, signal: r.signal, stdout: r.stdout, stderr: r.stderr };
  });
  process.stdout.write(JSON.stringify(out, null, 1) + '\n');
} else {
  const r = run(argv);
  process.stdout.write(JSON.stringify(r, null, 1) + '\n');
}
// Decode observed outputs for template "[T](..." into structured tuples,
// then compare against a candidate JS implementation of getLink().
import { readFileSync } from 'node:fs';

export function unescAttr(s) {
  return s.replace(/&quot;/g, '"').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&#10;/g, '\n').replace(/&amp;/g, '&');
}
export function unescText(s) {
  return s.replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&amp;/g, '&');
}

export function decode(input, output) {
  // expects <p>...</p>
  if (!output.startsWith('<p>') || !output.endsWith('</p>')) return { weird: true, output };
  const body = output.slice(3, -4);
  if (!body.startsWith('<a href="')) return { handled: false, body };
  let i = 9;
  let j = body.indexOf('"', i);
  const href = unescAttr(body.slice(i, j));
  let k = j + 1;
  let title = null;
  if (body.startsWith(' title="', k)) {
    k += 8;
    const e = body.indexOf('"', k);
    title = unescAttr(body.slice(k, e));
    k = e + 1;
  }
  if (body[k] !== '>') return { weird: true, output };
  k++;
  const close = body.indexOf('</a>', k);
  const text = body.slice(k, close);
  const rest = unescText(body.slice(close + 4));
  const end = input.length - rest.length;
  return { handled: true, href, title, text, rest, end };
}

if (process.argv[2] && process.argv[2].endsWith('.json')) {
  const rows = JSON.parse(readFileSync(process.argv[2], 'utf8'));
  const dec = rows.map((r) => ({ input: r.input, output: r.output, d: decode(r.input, r.output) }));
  if (process.argv[3] === '--dump') {
    for (const r of dec) console.log(JSON.stringify(r.input), '=>', JSON.stringify(r.d));
  }
}

