// Exact harness: recovers md(a) INCLUDING any trailing newlines it may have.
// The driver prints md(a) then md(b) etc, each with a trailing "\n" (print()).
// So stdout = md(a) + "\n" + md(SENT) + "\n" + ...
// md(SENT) == "<p>ZQXSENTINELB</p>" (verified). We locate that literal and
// take everything before it minus exactly one "\n".
import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';

const EXE = '/workspace/dataset/test16_executable';
const SENT = 'ZQXSENTINELB';
const MARK = '<p>' + SENT + '</p>\n';

export function mdExact(src) {
  const r = spawnSync(EXE, ['--a', src, '--b', SENT, '--c', 'C', '--d', 'D', '--e', 'E'], {
    encoding: 'utf8', maxBuffer: 1 << 28,
  });
  const stdout = r.stdout ?? '';
  const i = stdout.indexOf(MARK);
  if (i < 0) return { error: true, code: r.status, stderr: r.stderr, stdout };
  const pre = stdout.slice(0, i); // == md(a) + "\n"
  if (!pre.endsWith('\n')) return { error: true, reason: 'no print newline', pre };
  return { html: pre.slice(0, -1), code: r.status, stderr: r.stderr };
}

const argv = process.argv.slice(2);
if (argv.length) {
  const list = argv[0] === '--file' ? JSON.parse(readFileSync(argv[1], 'utf8')) : JSON.parse(argv[1]);
  const out = list.map((s) => {
    const r = mdExact(s);
    return { input: s, output: r.html ?? null, error: r.error ? (r.stderr || r.reason || 'err') : undefined };
  });
  process.stdout.write(JSON.stringify(out, null, 1) + '\n');
}

